window.kbPageData["views/entry/k-e307461a0d2033c3"] = {"key":"entry/k-e307461a0d2033c3","state":{"route":"entry/k-e307461a0d2033c3"},"node":{"id":"k-e307461a0d2033c3","mode":"k","title":"整体与子集的计数关系","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["同一统计口径下，整体的非负计数不小于其任一子集的计数"],"qs":["江苏 2024 A类 行测#135"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"在统计时期、计数单位和口径一致，且子集计入整体的条件下，整体计数至少等于子集计数。因此，子集计数超过某一数值时，整体计数也超过该数值。","review":{"definition":"在统计时期、计数单位和口径一致，且子集计入整体的条件下，整体计数至少等于子集计数。因此，子集计数超过某一数值时，整体计数也超过该数值。","explanation":"第135题中，重点监测电商平台的直播场次属于全行业直播场次。反推得2020年重点监测平台的直播场次超过2000万场，全行业至少包含这些场次，因此B项成立。解析中的「必然多于」需要另有至少一场未纳入监测的直播，推得B项只需全行业场次大于或等于监测范围内的场次。","references":[],"evidence":"2020年我国直播电商行业直播场次超过2000万场","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#135":{"paper":"江苏 2024 A类 行测","n":135,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",27],"asrc":["0126a1c8aceee632ea2b.pdf",41],"card":"1575acf39a119c0666990e5b","links":[{"id":"k-e307461a0d2033c3","role":"解题依据","why":"受监测平台是全行业的一部分，其场次超过的门槛也适用于全行业。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e307461a0d2033c3":[["江苏 2024 A类 行测#135"]]}};
